enum llama_vocab_type {
        LLAMA_VOCAB_TYPE_NONE   = 0,
        LLAMA_VOCAB_TYPE_SPM    = 1,
        LLAMA_VOCAB_TYPE_BPE    = 2,
        LLAMA_VOCAB_TYPE_WPM    = 3,
        LLAMA_VOCAB_TYPE_UGM    = 4,
        LLAMA_VOCAB_TYPE_RWKV   = 5,
        LLAMA_VOCAB_TYPE_PLAMO2 = 6,
    };

enum llama_rope_type {
        LLAMA_ROPE_TYPE_NONE   = -1,
        LLAMA_ROPE_TYPE_NORM   = 0,
        LLAMA_ROPE_TYPE_NEOX   = GGML_ROPE_TYPE_NEOX,
        LLAMA_ROPE_TYPE_MROPE  = GGML_ROPE_TYPE_MROPE,
        LLAMA_ROPE_TYPE_IMROPE = GGML_ROPE_TYPE_IMROPE,
        LLAMA_ROPE_TYPE_VISION = GGML_ROPE_TYPE_VISION,
    };

enum llama_token_type {
        LLAMA_TOKEN_TYPE_UNDEFINED    = 0,
        LLAMA_TOKEN_TYPE_NORMAL       = 1,
        LLAMA_TOKEN_TYPE_UNKNOWN      = 2,
        LLAMA_TOKEN_TYPE_CONTROL      = 3,
        LLAMA_TOKEN_TYPE_USER_DEFINED = 4,
        LLAMA_TOKEN_TYPE_UNUSED       = 5,
        LLAMA_TOKEN_TYPE_BYTE         = 6,
    };

enum llama_rope_scaling_type {
        LLAMA_ROPE_SCALING_TYPE_UNSPECIFIED = -1,
        LLAMA_ROPE_SCALING_TYPE_NONE        = 0,
        LLAMA_ROPE_SCALING_TYPE_LINEAR      = 1,
        LLAMA_ROPE_SCALING_TYPE_YARN        = 2,
        LLAMA_ROPE_SCALING_TYPE_LONGROPE    = 3,
        LLAMA_ROPE_SCALING_TYPE_MAX_VALUE   = LLAMA_ROPE_SCALING_TYPE_LONGROPE,
    };

enum llama_pooling_type {
        LLAMA_POOLING_TYPE_UNSPECIFIED = -1,
        LLAMA_POOLING_TYPE_NONE = 0,
        LLAMA_POOLING_TYPE_MEAN = 1,
        LLAMA_POOLING_TYPE_CLS  = 2,
        LLAMA_POOLING_TYPE_LAST = 3,
        LLAMA_POOLING_TYPE_RANK = 4,
    };

enum llama_attention_type {
        LLAMA_ATTENTION_TYPE_UNSPECIFIED = -1,
        LLAMA_ATTENTION_TYPE_CAUSAL      = 0,
        LLAMA_ATTENTION_TYPE_NON_CAUSAL  = 1,
    };

enum llama_flash_attn_type {
        LLAMA_FLASH_ATTN_TYPE_AUTO     = -1,
        LLAMA_FLASH_ATTN_TYPE_DISABLED = 0,
        LLAMA_FLASH_ATTN_TYPE_ENABLED  = 1,
    };

enum llama_split_mode {
        LLAMA_SPLIT_MODE_NONE  = 0,
        LLAMA_SPLIT_MODE_LAYER = 1,
        LLAMA_SPLIT_MODE_ROW   = 2,
    };

typedef struct llama_token_data {
        llama_token id;
        float logit;
        float p;
    } llama_token_data;

typedef struct llama_token_data_array {
        llama_token_data * data;
        size_t size;
        int64_t selected;
        bool sorted;
    } llama_token_data_array;

typedef struct llama_batch {
        int32_t n_tokens;

        llama_token  *  token;
        float        *  embd;
        llama_pos    *  pos;
        int32_t      *  n_seq_id;
        llama_seq_id ** seq_id;
        int8_t       *  logits;
    } llama_batch;

enum llama_model_kv_override_type {
        LLAMA_KV_OVERRIDE_TYPE_INT,
        LLAMA_KV_OVERRIDE_TYPE_FLOAT,
        LLAMA_KV_OVERRIDE_TYPE_BOOL,
        LLAMA_KV_OVERRIDE_TYPE_STR,
    };

struct llama_model_kv_override {
        enum llama_model_kv_override_type tag;

        char key[128];

        union {
            int64_t val_i64;
            double  val_f64;
            bool    val_bool;
            char    val_str[128];
        };
    };

struct llama_model_tensor_buft_override {
        const char * pattern;
        ggml_backend_buffer_type_t buft;
    };

struct llama_model_params {
        ggml_backend_dev_t * devices;
        const struct llama_model_tensor_buft_override * tensor_buft_overrides;
        int32_t n_gpu_layers;
        enum llama_split_mode split_mode;
        int32_t main_gpu;
        const float * tensor_split;
        llama_progress_callback progress_callback;
        void * progress_callback_user_data;
        const struct llama_model_kv_override * kv_overrides;
        bool vocab_only;
        bool use_mmap;
        bool use_mlock;
        bool check_tensors;
        bool use_extra_bufts;
        bool no_host;
    };

struct llama_context_params {
        uint32_t n_ctx;
        uint32_t n_batch;
        uint32_t n_ubatch;
        uint32_t n_seq_max;
        int32_t  n_threads;
        int32_t  n_threads_batch;

        enum llama_rope_scaling_type rope_scaling_type;
        enum llama_pooling_type      pooling_type;
        enum llama_attention_type    attention_type;
        enum llama_flash_attn_type   flash_attn_type;

        float    rope_freq_base;
        float    rope_freq_scale;
        float    yarn_ext_factor;
        float    yarn_attn_factor;
        float    yarn_beta_fast;
        float    yarn_beta_slow;
        uint32_t yarn_orig_ctx;
        float    defrag_thold;

        ggml_backend_sched_eval_callback cb_eval;
        void * cb_eval_user_data;

        enum ggml_type type_k;
        enum ggml_type type_v;

        ggml_abort_callback abort_callback;
        void *              abort_callback_data;

        bool embeddings;
        bool offload_kqv;
        bool no_perf;
        bool op_offload;
        bool swa_full;
        bool kv_unified;
    };

typedef struct llama_model_quantize_params {
        int32_t nthread;
        enum llama_ftype ftype;
        enum ggml_type output_tensor_type;
        enum ggml_type token_embedding_type;
        bool allow_requantize;
        bool quantize_output_tensor;
        bool only_copy;
        bool pure;
        bool keep_split;
        void * imatrix;
        void * kv_overrides;
        void * tensor_types;
        void * prune_layers;
    } llama_model_quantize_params;

typedef struct llama_logit_bias {
        llama_token token;
        float bias;
    } llama_logit_bias;

typedef struct llama_sampler_chain_params {
        bool no_perf;
    } llama_sampler_chain_params;

typedef struct llama_chat_message {
        const char * role;
        const char * content;
    } llama_chat_message;

struct llama_sampler_i {
        const char *           (*name)  (const struct llama_sampler * smpl);
        void                   (*accept)(      struct llama_sampler * smpl, llama_token token);
        void                   (*apply) (      struct llama_sampler * smpl, llama_token_data_array * cur_p);
        void                   (*reset) (      struct llama_sampler * smpl);
        struct llama_sampler * (*clone) (const struct llama_sampler * smpl);
        void                   (*free)  (      struct llama_sampler * smpl);
    };

struct llama_sampler {
        const struct llama_sampler_i * iface;
        llama_sampler_context_t        ctx;
    };

struct llama_perf_context_data {
        double t_start_ms;
        double t_load_ms;
        double t_p_eval_ms;
        double t_eval_ms;

        int32_t n_p_eval;
        int32_t n_eval;
        int32_t n_reused;
    };

struct llama_perf_sampler_data {
        double t_sample_ms;

        int32_t n_sample;
    };

struct llama_opt_params {
        uint32_t n_ctx_train;

        llama_opt_param_filter param_filter;
        void * param_filter_ud;

        ggml_opt_get_optimizer_params get_opt_pars;
        void * get_opt_pars_ud;

        enum ggml_opt_optimizer_type optimizer_type;
    };

struct llama_model_deleter {
    void operator()(llama_model * model) { llama_model_free(model); }
};

struct llama_context_deleter {
    void operator()(llama_context * context) { llama_free(context); }
};

struct llama_sampler_deleter {
    void operator()(llama_sampler * sampler) { llama_sampler_free(sampler); }
};

struct llama_adapter_lora_deleter {
    void operator()(llama_adapter_lora * adapter) { llama_adapter_lora_free(adapter); }
};

