// Choose a valid llama_flash_attn_type in {-1, 0, 1}
int sel = (int)(*FUZZ_PARAM(unsigned int) % 3);
enum llama_flash_attn_type ty = (enum llama_flash_attn_type)(sel == 0 ? -1 : (sel == 1 ? 0 : 1));
// Call the function; return value is a const char* which may be NULL for invalid, but we ensure valid enum
const char *name = llama_flash_attn_type_name(ty);
(void)name; // not asserted; API guarantees a readable name for valid values

// Get default model params (by value) and lightly perturb a few fields to exercise code paths
struct llama_model_params p = llama_model_default_params();
// Keep values small/safe per fuzzer perf guidance
p.n_gpu_layers = (int32_t)(*FUZZ_PARAM(unsigned int) % 3);
p.main_gpu     = (int32_t)(*FUZZ_PARAM(unsigned int) % 2);
p.vocab_only   = (*FUZZ_PARAM(unsigned int) & 1) != 0;
// Do not attempt to load a model here; just ensure the function can be called safely
(void)p;

// Get default context params and tweak to small, valid ranges
struct llama_context_params cp = llama_context_default_params();
cp.n_ctx          = 64 + (uint32_t)(*FUZZ_PARAM(unsigned int) % 128);   // small context
cp.n_batch        = 1 + (uint32_t)(*FUZZ_PARAM(unsigned int) % 8);
cp.n_ubatch       = 1 + (uint32_t)(*FUZZ_PARAM(unsigned int) % 8);
cp.n_seq_max      = 1 + (uint32_t)(*FUZZ_PARAM(unsigned int) % 4);
cp.n_threads      = 1 + (int32_t)(*FUZZ_PARAM(unsigned int) % 4);
cp.n_threads_batch= 1 + (int32_t)(*FUZZ_PARAM(unsigned int) % 4);
(void)cp;

// Obtain defaults for sampler chain
struct llama_sampler_chain_params sp = llama_sampler_chain_default_params();
sp.no_perf = (*FUZZ_PARAM(unsigned int) & 1) != 0;
(void)sp;

// Obtain default quantize params and perturb safely
struct llama_model_quantize_params qp = llama_model_quantize_default_params();
qp.nthread = 1 + (int32_t)(*FUZZ_PARAM(unsigned int) % 4);
// ftype remains default to avoid unsupported combos
(void)qp;

// Initialize backend once per process; guard with a global attribute
if (FUZZ_GET_ATTR_INT_GLOBAL("llama_backend_inited") == 0) {
    llama_backend_init();
    FUZZ_SET_ATTR_INT_GLOBAL("llama_backend_inited", 1);
    // Track live model/context counts for safe backend_free later
    FUZZ_SET_ATTR_INT_GLOBAL("llama_models_live", 0);
    FUZZ_SET_ATTR_INT_GLOBAL("llama_contexts_live", 0);
}

// Only finalize backend if it was initialized and no live models/contexts remain
if (FUZZ_GET_ATTR_INT_GLOBAL("llama_backend_inited") == 1) {
    int n_models = FUZZ_GET_ATTR_INT_GLOBAL("llama_models_live");
    int n_ctxs   = FUZZ_GET_ATTR_INT_GLOBAL("llama_contexts_live");
    if (n_models == 0 && n_ctxs == 0) {
        llama_backend_free();
        FUZZ_SET_ATTR_INT_GLOBAL("llama_backend_inited", 0);
    } else {
        // Backend cannot be freed yet; respect requirement to call after all objects are freed
        FUZZ_BAIL();
    }
}

// Choose a small valid ggml_numa_strategy value; use known small domain [0..3]
int v = (int)(*FUZZ_PARAM(unsigned int) % 4);
llama_numa_init((enum ggml_numa_strategy)v);

// Detach any previously attached threadpools; ctx must be valid
llama_detach_threadpool(ctx);
// ctx remains valid and is returned to the pool

// Ensure backend is initialized
if (FUZZ_GET_ATTR_INT_GLOBAL("llama_backend_inited") == 0) {
