if (!ctx) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT_GLOBAL("llama_contexts_live", FUZZ_GET_ATTR_INT_GLOBAL("llama_contexts_live") + 1);
// Track association for sanity (not enforced here)
FUZZ_SET_ATTR_PTR(ctx, "parent_model", (void*)model);
// Return both model (still owned by caller) and new context

// Deprecated alias of llama_init_from_model; still valid to exercise
struct llama_context_params cp = llama_context_default_params();
cp.n_ctx           = 64 + (uint32_t)(*FUZZ_PARAM(unsigned int) % 128);
