int live = FUZZ_GET_ATTR_INT_GLOBAL("llama_contexts_live");
if (live > 0) { FUZZ_SET_ATTR_INT_GLOBAL("llama_contexts_live", live - 1); }
// Do not return ctx

// Simple timing probe
int64_t t0 = llama_time_us();
(void)t0;

// Query max devices; no inputs or constraints
size_t n = llama_max_devices();
(void)n; // value may be 0 if no offload support
// Validation: trivial getter with no side effects; nothing to persist.

