float dry_multiplier      = (float)((int)(*FUZZ_PARAM(unsigned int) % 400) + 50) / 100.0f; // [0.5,4.5]
float dry_base            = (float)((int)(*FUZZ_PARAM(unsigned int) % 200)) / 100.0f;      // [0,2)
