FUZZ_SET_ATTR_INT(smpl, "is_chain", 0);
FUZZ_SET_ATTR_STR(smpl, "sampler_kind", "dry");
FUZZ_SET_ATTR_INT(smpl, "owned_by_chain", 0);
// Validation: sourced n_ctx_train from model; vocab valid; arrays small/optional; non-null sampler.

// Logit-bias sampler requires n_vocab and an array of biases
const struct llama_vocab * vocab = llama_model_get_vocab(model);
if (!vocab) { FUZZ_BAIL(); }
int32_t n_vocab = llama_vocab_n_tokens(vocab);
