if (!smpl) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(smpl, "is_chain", 0);
FUZZ_SET_ATTR_STR(smpl, "sampler_kind", "logit_bias");
FUZZ_SET_ATTR_INT(smpl, "owned_by_chain", 0);
// Validation: n_vocab taken from model; valid tokens and small bias list; non-null sampler.

// Infill sampler requires a valid vocab
const struct llama_vocab * vocab = llama_model_get_vocab(model);
if (!vocab) { FUZZ_BAIL(); }
struct llama_sampler * smpl = llama_sampler_init_infill(vocab);
if (!smpl) { FUZZ_BAIL(); }
