FUZZ_SET_ATTR_STR(smpl, "sampler_kind", "infill");
FUZZ_SET_ATTR_INT(smpl, "owned_by_chain", 0);
// Validation: vocab non-null; sampler non-null; metadata set.

// Query RNG seed used by sampler (or default)
uint32_t seed = llama_sampler_get_seed(smpl);
(void)seed;
// Validation: simple getter; sampler preserved.

// Ensure logits are available by performing a successful decode with logits requested
llama_token tok = (llama_token)((int32_t)(*FUZZ_PARAM(unsigned int) % 256));
struct llama_batch b = llama_batch_get_one(&tok, 1);
if (b.logits) { b.logits[0] = 1; }
int32_t rc = llama_decode(ctx, b);
if (rc != 0) { llama_batch_free(b); FUZZ_BAIL(); }
// Pick idx as 0 or -1 (reverse index for last)
int use_rev = (*FUZZ_PARAM(unsigned int) & 1u) != 0;
int32_t idx = use_rev ? -1 : 0;
