// Validation: ensured recent logits exist; idx constrained; both objects preserved.

// Build a split filename from prefix and indices
size_t cap = 256;
std::vector<char> buf(cap);
std::string prefix = FUZZ_PARAM_STR();
int split_count = (int)(*FUZZ_PARAM(unsigned int) % 8) + 1; // >0
