// Query system/build info string
const char * info = llama_print_system_info();
(void)info;
// Validation: pure getter; no side effects.

// Set global log callback to NULL to reset to stderr
llama_log_set(/*log_callback*/NULL, /*user_data*/NULL);
// Validation: NULL callback allowed; global state updated safely.

// Retrieve performance statistics for context
struct llama_perf_context_data perf = llama_perf_context(ctx);
(void)perf;
// Validation: getter on valid ctx; ctx preserved.

// Print context performance stats via logging
llama_perf_context_print(ctx);
// Validation: side-effect is logging; ctx preserved.

// Reset performance counters/timers
llama_perf_context_reset(ctx);
// Validation: state reset; ctx preserved.

// Only valid for chains created by llama_sampler_chain_init
if (FUZZ_GET_ATTR_INT(chain, "is_chain") != 1) { FUZZ_BAIL(); }
struct llama_perf_sampler_data p = llama_perf_sampler(chain);
(void)p;
