// Print sampler chain performance stats
if (FUZZ_GET_ATTR_INT(chain, "is_chain") != 1) { FUZZ_BAIL(); }
llama_perf_sampler_print(chain);
// Validation: enforced chain precondition; chain preserved.

// Reset performance counters for sampler chain
if (FUZZ_GET_ATTR_INT(chain, "is_chain") != 1) { FUZZ_BAIL(); }
llama_perf_sampler_reset(chain);
// Validation: chain type enforced; chain preserved.

// Print memory usage breakdown
llama_memory_breakdown_print(ctx);
// Validation: logging side effect only; ctx preserved.

// Utility filter that returns true for all tensors; arguments are ignored
bool ok = llama_opt_param_filter_all(/*tensor*/NULL, /*userdata*/NULL);
(void)ok;
// Validation: function is argument-agnostic by design; safe to call with NULLs.

// Validate that the context belongs to the provided model
struct llama_model * parent = (struct llama_model *)FUZZ_GET_ATTR_PTR(lctx, "parent_model");
if (parent == NULL || parent != model) { FUZZ_BAIL(); }

// Prepare optimization parameters with safe, small values
