import random
import string
from typing import List

# This generator targets plain text inputs used by llama_tokenize and llama_chat_apply_template fuzzers.
# Goals:
# - Produce a variety of UTF-8 strings, including ASCII, Unicode, whitespace patterns, control-like sequences,
#   special-token-like markers, and lengths ranging from empty to moderately long.
# - Include sequences that may resemble special tokens used in LLMs (e.g., <s>, </s>, <|eot|>, <|endoftext|>, <bos>, <eos>, <pad>, <mask>, <fim_*>),
#   as these can exercise add_special/parse_special branches.
# - Include repeated patterns, newlines, tabs, and multi-message like blocks to exercise chat template formatting.
# - Keep result under 4096 bytes.

MAX_BYTES = 4096

UNICODE_BLOCKS = [
    (0x0020, 0x007E),  # Basic printable ASCII
    (0x00A0, 0x00FF),  # Latin-1 Supplement
    (0x0100, 0x017F),  # Latin Extended-A
    (0x0370, 0x03FF),  # Greek
    (0x0400, 0x04FF),  # Cyrillic
    (0x0530, 0x058F),  # Armenian
    (0x0590, 0x05FF),  # Hebrew
    (0x0600, 0x06FF),  # Arabic
    (0x0900, 0x097F),  # Devanagari
    (0x3040, 0x309F),  # Hiragana
    (0x30A0, 0x30FF),  # Katakana
    (0x4E00, 0x9FFF),  # CJK Unified Ideographs
    (0x1F300, 0x1F64F),# Emojis (misc symbols & pictographs)
]

SPECIAL_TOKENS = [
    "<s>", "</s>", "<bos>", "<eos>", "<pad>", "<mask>",
    "<|bos|>", "<|eos|>", "<|pad|>", "<|mask|>", "<|unk|>",
    "<|endoftext|>", "<|eot|>", "<|eom|>", "<|fim_begin|>",
    "<|fim_end|>", "<|fim_hole|>", "<|fim_middle|>",
    "<|assistant|>", "<|user|>", "<|system|>",
]

ROLES = ["user", "assistant", "system", "tool", "function", "developer"]

WHITESPACE_RUNS = [
    " ", "\t", "\n", "\r\n", "\n\n", "\t\t", "    ",
]

PUNCT_RUNS = [
    "...", "—", "–", "::", ";;", "??", "!!", "!?", ",,", ". ", ": ", "; ",
]

def rand_unicode_char(rng: random.Random) -> str:
    block = rng.choice(UNICODE_BLOCKS)
    for _ in range(10):
        cp = rng.randint(block[0], block[1])
        # Skip surrogate range and non-characters
        if 0xD800 <= cp <= 0xDFFF:
            continue
        if (cp & 0xFFFE) == 0xFFFE:
            continue
        try:
            ch = chr(cp)
            ch.encode('utf-8')
            return ch
        except UnicodeEncodeError:
            continue
    return rng.choice(string.ascii_letters)

def rand_word(rng: random.Random) -> str:
    modes = ["ascii", "unicode", "num", "mix"]
    m = rng.choice(modes)
    if m == "ascii":
        length = rng.randint(1, 12)
        return ''.join(rng.choice(string.ascii_letters) for _ in range(length))
    if m == "num":
        length = rng.randint(1, 8)
        return ''.join(rng.choice(string.digits) for _ in range(length))
    if m == "unicode":
        length = rng.randint(1, 6)
        return ''.join(rand_unicode_char(rng) for _ in range(length))
    # mix
    length = rng.randint(2, 12)
    s = []
    for _ in range(length):
        pick = rng.random()
        if pick < 0.5:
            s.append(rng.choice(string.ascii_lowercase))
        elif pick < 0.7:
            s.append(rng.choice(string.ascii_uppercase))
        elif pick < 0.85:
            s.append(rng.choice(string.digits))
        else:
            s.append(rand_unicode_char(rng))
    return ''.join(s)

def rand_sentence(rng: random.Random) -> str:
    parts: List[str] = []
    n_words = rng.randint(3, 20)
    for i in range(n_words):
        if rng.random() < 0.12:
            parts.append(rng.choice(SPECIAL_TOKENS))
        else:
            parts.append(rand_word(rng))
        if i != n_words - 1:
            # occasional punctuation or whitespace glue
            if rng.random() < 0.2:
                parts.append(rng.choice(PUNCT_RUNS))
            else:
                parts.append(' ')
    # End punctuation
    if rng.random() < 0.5:
        parts.append(rng.choice([".", "?", "!", "\n"]))
    return ''.join(parts)

def rand_paragraph(rng: random.Random) -> str:
    sents = rng.randint(1, 5)
    out = []
    for i in range(sents):
        out.append(rand_sentence(rng))
        if i != sents - 1:
            out.append(rng.choice([" ", "\n", "\n\n", "\t"]))
    return ''.join(out)

def role_heading(r: str) -> str:
    # Common chat heading patterns used by templates
    # Include a few variants to engage template parsing
    return rng.choice([
        f"{r}: ",
        f"[{r}] ",
        f"<|{r}|> ",
        f"<<{r}>> ",
    ])

def build_chat_like_block(rng: random.Random) -> str:
    n = rng.randint(1, 5)
    lines = []
    for _ in range(n):
        role = rng.choice(ROLES)
        # Some templates rely on explicit role markers
        if rng.random() < 0.4:
            lines.append(f"<|{role}|>\n")
        else:
            lines.append(f"{role}:\n")
        # Content body
        body_parts = []
        m = rng.randint(1, 4)
        for i in range(m):
            if rng.random() < 0.15:
                body_parts.append(rng.choice(SPECIAL_TOKENS))
            else:
                body_parts.append(rand_paragraph(rng))
            if i != m - 1:
                body_parts.append(rng.choice(["\n", "\n\n", " ", "\t"]))
        lines.append(''.join(body_parts))
        lines.append("\n\n")
    # Optionally include stop/eot markers
    if rng.random() < 0.5:
        lines.append(rng.choice(["<|eot|>\n", "</s>\n", "<|endoftext|>\n"]))
    return ''.join(lines)

def build_fim_prompt(rng: random.Random) -> str:
    # A FIM-style prompt with special delimiters present in some models
    pre = rand_paragraph(rng)
    mid = rand_paragraph(rng)
    suf = rand_paragraph(rng)
    markers = rng.choice([
        ("<|fim_begin|>", "<|fim_hole|>", "<|fim_end|>"),
        ("<s>", "<mask>", "</s>"),
    ])
    return f"{markers[0]}{pre}{markers[1]}{mid}{markers[2]}{suf}"

def build_mixture(rng: random.Random) -> str:
    parts = []
    # Leading/trailing whitespace runs
    if rng.random() < 0.7:
        parts.append(rng.choice(WHITESPACE_RUNS))
    # BOS/EOS or not
    if rng.random() < 0.5:
        parts.append(rng.choice(["<s>", "<|bos|>"]))
    # Some paragraphs and special tokens interleaved
    k = rng.randint(1, 4)
    for i in range(k):
        parts.append(rand_paragraph(rng))
        if rng.random() < 0.3:
            parts.append(rng.choice(SPECIAL_TOKENS))
        if i != k - 1:
            parts.append(rng.choice(["\n", "\n\n", " ", "\t"]))
    if rng.random() < 0.5:
        parts.append(rng.choice(["</s>", "<|eos|>"]))
    if rng.random() < 0.7:
        parts.append(rng.choice(WHITESPACE_RUNS))
    return ''.join(parts)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a scenario
    scenario = rng.choice([
        "empty",            # empty string
        "short_ascii",      # small ASCII content
        "unicode",          # rich unicode text
        "paragraphs",       # multiple paragraphs
        "chat_like",        # role/content style blocks
        "fim",              # FIM-style special markers
        "mixture",          # mixed content with specials
        "repetition",       # repeated segments
    ])

    if scenario == "empty":
        s = ""
    elif scenario == "short_ascii":
        words = [rand_word(rng) for _ in range(rng.randint(1, 8))]
        s = ' '.join(words)
    elif scenario == "unicode":
        lines = []
        for _ in range(rng.randint(1, 5)):
            lines.append(''.join(rand_unicode_char(rng) for _ in range(rng.randint(4, 24))))
        s = '\n'.join(lines)
    elif scenario == "paragraphs":
        paras = [rand_paragraph(rng) for _ in range(rng.randint(1, 4))]
        s = '\n\n'.join(paras)
    elif scenario == "chat_like":
        s = build_chat_like_block(rng)
    elif scenario == "fim":
        s = build_fim_prompt(rng)
    elif scenario == "mixture":
        s = build_mixture(rng)
    else:  # repetition
        base = rand_sentence(rng)
        nrep = rng.randint(2, 8)
        glue = rng.choice(["\n", "\n\n", " ", "\t", "" ])
        s = glue.join(base for _ in range(nrep))

    # Ensure size constraint and valid UTF-8
    b = s.encode('utf-8', errors='strict')
    if len(b) > MAX_BYTES:
        b = b[:MAX_BYTES]
        # avoid cutting in middle of multi-byte utf-8: backtrack to valid boundary
        # find last valid prefix
        i = len(b)
        while i > 0 and (b[i-1] & 0xC0) == 0x80:
            i -= 1
        b = b[:i]
    return b
